public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address (case-insensitive). Returns the earliest-created matching Contact.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect normalized emails
        Set<String> emails = new Set<String>();
        for (Request req : requests) {
            String normalized = normalize(req == null ? null : req.email);
            if (String.isNotBlank(normalized)) {
                emails.add(normalized);
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!emails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emails
                ORDER BY CreatedDate ASC
            ];
            for (Contact c : contacts) {
                String key = normalize(c.Email);
                if (key != null && !emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        for (Request req : requests) {
            Result r = new Result();
            String normalized = normalize(req == null ? null : req.email);
            Id contactId = String.isNotBlank(normalized) ? emailToContactId.get(normalized) : null;
            r.contactId = contactId;
            r.found = contactId != null;
            results.add(r);
        }

        return results;
    }

