```apex
/**
 * Queueable job that marks Accounts as synced to the ERP system.
 * A Finalizer is attached so that every run is logged and failed runs are retried.
 */
public class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer first so that every outcome is logged/retried.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, Description = 'Synced to ERP'));
        }

        if (!accountsToUpdate.isEmpty()) {
            // All-or-nothing: an exception propagates and fails the job.
            update accountsToUpdate;
        }
    }
