/**
 * Domain class for the Opportunity SObject.
 *
 * Applies the org's defaulting rules to newly created Opportunities:
 *  - CloseDate defaults to today + 30 days when left blank
 *  - Type defaults to 'New Customer' when left blank
 * Existing values are preserved, and nothing is applied on update.
 */
public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    /**
     * Used by fflib_SObjectDomain.triggerHandler to instantiate this domain
     * class from the trigger context records.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Called by the fflib framework during the before insert phase only,
     * so the defaults are never applied on update.
     */
    public override void onApplyDefaults() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.CloseDate == null) {
                opp.CloseDate = Date.today().addDays(30);
            }
            if (String.isBlank(opp.Type)) {
                opp.Type = 'New Customer';
            }
        }
    }
}
