public with sharing class ContactEmailMatcher {

    public class Request {
        @InvocableVariable(required=true) public String email;
    }

    public class Result {
        @InvocableVariable public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            String normalized = normalize(req == null ? null : req.email);
            if (normalized != null) {
                normalizedEmails.add(normalized);
            }
        }

        Map<String, Contact> bestByEmail = new Map<String, Contact>();
        if (!normalizedEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :normalizedEmails
            ]) {
                String key = normalize(c.Email);
                if (key == null) continue;
                Contact existing = bestByEmail.get(key);
                if (existing == null || isBetter(c, existing)) {
                    bestByEmail.put(key, c);
                }
            }
        }

        for (Request req : requests) {
            Result r = new Result();
            String key = normalize(req == null ? null : req.email);
            Contact match = key == null ? null : bestByEmail.get(key);
            r.contactId = match == null ? null : match.Id;
            results.add(r);
        }
        return results;
    }

    private static String normalize(String value) {
        if (value == null) return null;
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed.toLowerCase();
    }

    private static Boolean isBetter(Contact candidate, Contact current) {
        if (candidate.CreatedDate < current.CreatedDate) return true;
        if (candidate.CreatedDate > current.CreatedDate) return false;
        return String.valueOf(candidate.Id) < String.valueOf(current.Id);
    }
}
