import LABEL_ADD from '@salesforce/label/c.Favorite_Add';
import LABEL_REMOVE from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    label = {
        add: LABEL_ADD,
        remove: LABEL_REMOVE
    };

    // Internal reactive state that drives the UI.
    _favorite = false;

    /**
     * Public boolean property set by the parent. The parent can change it at
     * any time (for example after a server refresh) and the getter/setter pair
     * keeps the rendered state in sync with that value.
     */
    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        this._favorite = value === true;
    }

    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    // Label of the action a click performs.
    get actionLabel() {
        return this._favorite ? this.label.remove : this.label.add;
    }

    handleClick() {
        // Optimistic UI: flip the displayed state immediately.
        this._favorite = !this._favorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this._favorite }
            })
        );
    }
}
