import { LightningElement, api } from 'lwc';

let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label = '';

    _uid = `status-listbox-${++instanceCounter}`;
    _options = [];
    _value = '';
    _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(options) {
        const list = Array.isArray(options) ? options : [];
        this._options = list.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${this._uid}-option-${index}`
        }));
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value === undefined || value === null ? '' : value;
        this._syncActiveIndex();
    }

    get computedOptions() {
        return this._options.map((option) => ({
            ...option,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendant() {
        const option = this._options[this._activeIndex];
        return option ? option.id : undefined;
    }

    _syncActiveIndex() {
        const index = this._options.findIndex((option) => option.value === this._value);
        this._activeIndex = index >= 0 ? index : 0;
    }

    _clampIndex(index) {
        if (this._options.length === 0) return 0;
        if (index < 0) return 0;
        if (index > this._options.length - 1) return this._options.length - 1;
        return index;
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = false;
        switch (key) {
            case 'ArrowDown':
                this._activeIndex = this._clampIndex(this._activeIndex + 1);
                handled = true;
                break;
            case 'ArrowUp':
                this._activeIndex = this._clampIndex(this._activeIndex - 1);
                handled = true;
                break;
            case 'Home':
                this._activeIndex = this._clampIndex(0);
                handled = true;
                break;
            case 'End':
                this._activeIndex = this._clampIndex(this._options.length - 1);
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this._selectActiveOption();
                handled = true;
                break;
            default:
                break;
        }
        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const index = this._options.findIndex(
            (option) => option.id === event.currentTarget.id
        );
        if (index < 0) return;
        this._activeIndex = index;
        this._selectOption(index);
        const list = this.template.querySelector('ul');
        if (list) {
            list.focus();
        }
    }

    _selectActiveOption() {
        this._selectOption(this._activeIndex);
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) return;
        if (option.value === this._value) return;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
