```js
import { LightningElement, api } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    @api label = '';

    _uid = `status-listbox-${++instanceCount}`;
    _options = [];
    _value = '';
    _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }

    set options(options) {
        const list = Array.isArray(options) ? options : [];
        this._options = list.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${this._uid}-option-${index}`
        }));
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value === undefined || value === null ? '' : value;
        this._syncActiveIndex();
    }

    get computedOptions() {
        return this._options.map((option) => ({
            ...option,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendant() {
        const option = this._options[this._activeIndex];
        return option ? option.id : undefined;
    }

    _syncActiveIndex() {
        const index = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = index >= 0 ? index : 0;
    }

    _normalizeIndex(index) {
        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return 0;
        }
        return Math.min(Math.max(index, 0), lastIndex);
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = false;

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = this._normalizeIndex(this._activeIndex + 1);
                handled = true;
                break;
            case 'ArrowUp':
                this._activeIndex = this._normalizeIndex(this._activeIndex - 1);
                handled = true;
                break;
            case 'Home':
                this._activeIndex = this._normalizeIndex(0);
                handled = true;
                break;
            case 'End':
                this._activeIndex = this._normalizeIndex(this._options.length - 1);
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this._selectOption(this._activeIndex);
                handled = true;
                break;
            default:
                break;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const clicked = event.currentTarget;
        const index = this._options.findIndex((option) => option.id === clicked.id);
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this._selectOption(index);
        const list = this.template.querySelector('ul');
        if (list) {
            list.focus();
        }
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        if (option.value === this._value) {
            return;
        }
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
                bubbles: true,
                composed: true
            })
        );
    }
}
```

