```apex
/**
 * @description Service that moves books of business between owners.
 *
 *              Account ownership changes must NOT run any of the Account trigger
 *              actions (they recalculate territories and are expensive), so the
 *              Account SObject is bypassed in the Trigger Actions Framework for
 *              the duration of the change and restored afterwards - even when the
 *              DML fails.
 *
 *              Contact trigger actions continue to run normally.
 */
public with sharing class AccountOwnershipService {
    private static final String ACCOUNT_SOBJECT_API_NAME = 'Account';

    /**
     * @description Reassigns the supplied Accounts and all of their Contacts to
     *              the given owner.
     * @param accountIds  Accounts whose owner (and whose Contacts' owner) changes.
     * @param newOwnerId  The new OwnerId to apply.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Query 1: every Contact that belongs to the supplied Accounts.
        List<Contact> contactsToReassign = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        List<Account> accountsToReassign = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToReassign.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }
        for (Contact contactRecord : contactsToReassign) {
            contactRecord.OwnerId = newOwnerId;
        }

        // Bypass the whole Account SObject so no Account trigger action runs.
        TriggerActionBypass.bypass(ACCOUNT_SOBJECT_API_NAME);
        try {
            // DML 1: all-or-none. Exceptions propagate unchanged to the caller.
            update accountsToReassign;

            // DML 2: all-or-none. Contact trigger actions run normally.
            update contactsToReassign;
        } finally {
            // Always restore Account automation for the rest of the transaction.
            TriggerActionBypass.clearBypass(ACCOUNT_SOBJECT_API_NAME);
        }
    }
}
```

